```html
<nav class="main-navigation" role="navigation" aria-label="Main Navigation">
 <ul class="nav-list" role="list">
 <li><a href="#home" class="nav-link" tabindex="0" aria-current="page">Home</a></li>
 <li><a href="#about" class="nav-link" tabindex="0">About Us</a></li>
