 border-radius: 5px;
 margin: 10px;
}
.accordion-item {
 margin: 5px 0;
}
.accordion-header {
 background-color: #f9f9f9;
 cursor: pointer;
 padding: 10px;
 width: 100%;
 text-align: left;
 outline: none;
 border: none;
 transition: background-color 0.3s ease;
}
.accordion-header:hover {
 background-color: #e6e6e6;
}
.accordion-content {
