 border-top: 1px solid #ddd;
}
</style>
```

### JavaScript with AJAX
```javascript
function toggleAccordion(contentId) {
 const contentElement = document.getElementById(contentId);
 if (contentElement.style.display === "block") {
 contentElement.style.display = "none";
 } else {
 contentElement.style.display = "block";
 loadContent(contentId);
 }
}

function loadContent(contentId) {
 const url = `https://api.example.com/data/${contentId}`;
 fetch(url)
 .then(response => response.json())
 .then(data => {
 document.getElementById(contentId).innerHTML = `<p>${data.content}</p>`;
 })
 .catch(error => console.error('Error fetching content:', error));
}
```

### Explanation:
- **HTML Structure**: The accordion consists of multiple `<div>` elements, each representing a section.
- **CSS**: Provides basic styling with hover effects for the headers.
- **JavaScript**: `toggleAccordion` toggles visibility of content, while `loadContent` fetches content using a simulated API endpoint.

