```html
<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Modal Window Example</title>
 <style>
 body { font-family: Arial, sans-serif; margin: 0; padding: 0; box-sizing: border-box; }
 .modal-overlay {
 position: fixed;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 background-color: rgba(0, 0, 0, 0.5);
 display: none;
 justify-content: center;
 align-items: center;
 }
 .modal {
 background-color: #fff;
 padding: 20px;
 width: 300px;
 border-radius: 5px;
 box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
 }
 .modal-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 }
 .modal-title {
 margin: 0;
 }
 .close-button {
 cursor: pointer;
 font-size: 1.2em;
 background: none;
 border: none;
 }
 </style>
</head>
<body>
 <button id="openModal">Open Modal</button>

 <div class="modal-overlay" id="modalOverlay">
 <div class="modal" role="dialog" aria-labelledby="modalTitle" aria-modal="true">
 <div class="modal-header">
 <h3 id="modalTitle" class="modal-title">Modal Title</h3>
 <button class="close-button" aria-label="Close" id="closeModal">&times;</button>
 </div>
 <div class="modal-content">
 <p>This is the modal content. You can include text, images, or any HTML elements here.</p>
 </div>
 </div>
 </div>

 <script>
 const openModalButton = document.getElementById('openModal');
 const modalOverlay = document.getElementById('modalOverlay');
 const closeModalButton = document.getElementById('closeModal');

 openModalButton.addEventListener('click', () => {
 modalOverlay.style.display = 'flex';
 });

 closeModalButton.addEventListener('click', () => {
 modalOverlay.style.display = 'none';
 });
 </script>
</body>
</html>
```

