 transition: background-color 0.3s ease;
 }
 .nav-link:hover, .nav-link:focus {
 background-color: #575757;
 outline: none;
 }
 /* Responsive design for smaller screens */
 @media (max-width: 768px) {
 .nav-menu {
 flex-direction: column;
 width: 100%;
 }
 .nav-item {
 margin-bottom: 10px;
 }
 }
 </style>
</head>
