 <title>Slide-in Modal Example</title>
 <style>
 body {
 font-family: Arial, sans-serif;
 margin: 0;
 padding: 0;
 background-color: #f4f4f9;
 }
 .modal {
 display: none;
 position: fixed;
 top: 0;
 left: 0;
 right: 0;
 bottom: 0;
 background-color: rgba(0, 0, 0, 0.5);
 justify-content: center;
 align-items: center;
 }
 .modal-content {
 background-color: #fff;
 padding: 20px;
