 width: 300px;
 box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
 transform: translateY(-300px);
 transition: transform 0.3s ease-out;
 }
 .modal.show .modal-content {
 transform: translateY(0);
 }
 .modal-header {
 margin-bottom: 15px;
 }
 .modal-footer {
 text-align: right;
 }
 .close-btn {
 background-color: #007bff;
 color: white;
 border: none;
 padding: 10px 20px;
 border-radius: 5px;
 cursor: pointer;
 }
 </style>
</head>
<body>

 <button id="openModalBtn">Open Modal</button>

 <div id="myModal" class="modal">
 <div class="modal-content">
 <div class="modal-header">
 <h2>Modal Header</h2>
 </div>
 <div class="modal-body">
 <p>This is a simple modal with a slide-in effect!</p>
 </div>
 <div class="modal-footer">
 <button class="close-btn" id="closeModalBtn">Close</button>
 </div>
 </div>
 </div>

 <script>
 const openModalBtn = document.getElementById('openModalBtn');
 const closeModalBtn = document.getElementById('closeModalBtn');
 const modal = document.getElementById('myModal');

 openModalBtn.addEventListener('click', () => {
 modal.style.display = 'flex';
 modal.classList.add('show');
 });

 closeModalBtn.addEventListener('click', () => {
 modal.classList.remove('show');
 setTimeout(() => {
 modal.style.display = 'none';
 }, 300);
 });
 </script>

</body>
</html>
```

**Explanation:**
- This code defines a simple modal window that appears when a button is clicked.
- The modal slides in from above, offering a smooth transition effect.
- The modal can be closed by clicking the "Close" button, which slides it out and hides it.

