 @media screen and (max-width: 600px) {
 .nav-bar.responsive {position: relative;}
 .nav-bar.responsive .icon {
 position: absolute;
 right: 0;
 top: 0;
 }
 .nav-bar.responsive a {
 float: none;
 display: block;
 text-align: left;
 }
 }
 </style>
</head>
<body>
