<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Drag and Drop Interface</title>
 <style>
 .drag-container {
 display: flex;
 gap: 10px;
 margin-top: 20px;
 }
 .draggable-item, .drop-zone {
 border: 2px dashed #ccc;
 padding: 20px;
 width: 100px;
 height: 100px;
 display: flex;
 align-items: center;
 justify-content: center;
 cursor: move;
 }
 .draggable-item {
 background-color: #f0f0f0;
 }
 .drop-zone {
 background-color: #e0ffe0;
 }
 </style>
</head>
<body>
 <h1>Simple Drag and Drop</h1>
 <div class="drag-container">
 <div class="draggable-item" draggable="true">Drag me!</div>
 <div class="drop-zone">Drop here</div>
 </div>
 <script>
 const draggableItem = document.querySelector('.draggable-item');
 const dropZone = document.querySelector('.drop-zone');

 draggableItem.addEventListener('dragstart', (e) => {
 e.dataTransfer.setData('text/plain', e.target.id);
 });

 dropZone.addEventListener('dragover', (e) => {
 e.preventDefault();
 });

 dropZone.addEventListener('drop', (e) => {
 e.preventDefault();
 const data = e.dataTransfer.getData('text/plain');
 e.target.appendChild(draggableItem);
 });
 </script>
</body>
</html>
```

