 align-items: center;
 padding: 10px 20px;
 background-color: #333;
 color: #fff;
 }

 .logo h1 {
 font-size: 1.5em;
 }

 .main-nav {
 position: relative;
 }

 .nav-toggle {
 background: none;
 border: none;
 cursor: pointer;
 display: none;
 }

 .hamburger {
 width: 25px;
 height: 3px;
 background-color: #fff;
 display: block;
 position: relative;
 transition: all 0.3s;
 }

 .hamburger::before, .hamburger::after {
 content: '';
 position: absolute;
 width: 100%;
 height: 100%;
 background-color: #fff;
 transition: all 0.3s;
 }

 .hamburger::before {
 transform: translateY(-8px);
 }

 .hamburger::after {
 transform: translateY(8px);
 }

 .nav-list {
 display: flex;
 list-style: none;
 }

 .nav-list li {
 margin: 0 10px;
 }

 .nav-list a {
 color: #fff;
 text-decoration: none;
 padding: 5px 10px;
 }

 @media (max-width: 768px) {
 .nav-list {
 display: none;
 flex-direction: column;
 }

 .nav-toggle {
 display: inline-block;
 }

 .nav-toggle[aria-expanded="true"] .nav-list {
 display: flex;
 }
 }
</style>
```

