<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Autoplay Carousel Slider</title>
 <style>
 .carousel {
 position: relative;
 overflow: hidden;
 width: 100%;
 max-width: 800px;
 margin: auto;
 }
 .carousel-inner {
 display: flex;
 transition: transform 0.5s ease-in-out;
 }
 .carousel-item {
 min-width: 100%;
 box-sizing: border-box;
 }
 .carousel img {
 width: 100%;
 display: block;
 }
 .carousel-controls {
 position: absolute;
 top: 50%;
 width: 100%;
 display: flex;
 justify-content: space-between;
 transform: translateY(-50%);
 }
 .carousel-controls button {
 background-color: rgba(0, 0, 0, 0.5);
 border: none;
 color: white;
 padding: 10px;
 cursor: pointer;
 }
 </style>
</head>
<body>
 <div class="carousel">
 <div class="carousel-inner" id="carousel">
 <div class="carousel-item">
 <img src="image1.jpg" alt="First Slide">
 </div>
 <div class="carousel-item">
 <img src="image2.jpg" alt="Second Slide">
 </div>
 <div class="carousel-item">
 <img src="image3.jpg" alt="Third Slide">
 </div>
 </div>
 <div class="carousel-controls">
 <button onclick="previousSlide()">&#10094;</button>
 <button onclick="nextSlide()">&#10095;</button>
 </div>
 </div>
 <script>
 let index = 0;
 const slides = document.querySelectorAll('.carousel-item');
 const totalSlides = slides.length;

 function showSlide(slideIndex) {
 const carousel = document.getElementById('carousel');
 if(slideIndex >= totalSlides) { index = 0; }
 if(slideIndex < 0) { index = totalSlides - 1; }
 carousel.style.transform = `translateX(-${index * 100}%)`;
 }

 function nextSlide() {
 index++;
 showSlide(index);
 }

 function previousSlide() {
 index--;
 showSlide(index);
 }

 setInterval(nextSlide, 3000); // Change slide every 3 seconds
 </script>
</body>
</html>
```

