Here's a complete HTML snippet with CSS:

```html
<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Responsive Video Slider</title>
 <style>
 body {
 margin: 0;
 font-family: Arial, sans-serif;
 }
 .slider-container {
 max-width: 100%;
 position: relative;
 overflow: hidden;
 }
 .slider {
 display: flex;
 transition: all 0.5s ease;
 }
 .video-slide {
 min-width: 100%;
 box-sizing: border-box;
 }
 video {
 width: 100%;
 height: auto;
 }
 .navigation {
 position: absolute;
 top: 50%;
 width: 100%;
 display: flex;
 justify-content: space-between;
 transform: translateY(-50%);
 }
 .prev, .next {
 background-color: rgba(0, 0, 0, 0.5);
 color: white;
 padding: 10px;
 cursor: pointer;
 }
 </style>
</head>
<body>
 <div class="slider-container">
 <div class="slider" id="videoSlider">
 <div class="video-slide">
 <video src="video1.mp4" controls></video>
 </div>
 <div class="video-slide">
 <video src="video2.mp4" controls></video>
 </div>
 <div class="video-slide">
 <video src="video3.mp4" controls></video>
 </div>
 </div>
 <div class="navigation">
 <div class="prev" onclick="moveSlide(-1)">❮</div>
 <div class="next" onclick="moveSlide(1)">❯</div>
 </div>
 </div>
 <script>
 let currentSlide = 0;
 const slides = document.querySelectorAll('.video-slide');
 function moveSlide(direction) {
 currentSlide = (currentSlide + direction + slides.length) % slides.length;
 document.getElementById('videoSlider').style.transform = `translateX(-${currentSlide * 100}%)`;
 }
 </script>
</body>
</html>
```

