 border-bottom: 1px solid #555;
 }
 .hamburger {
 cursor: pointer;
 font-size: 30px;
 }
 @media (min-width: 768px) {
 .nav-menu {
 display: flex;
 flex-direction: row;
 }
 .nav-menu a {
 border: none;
 padding: 0 15px;
 }
 .hamburger {
 display: none;
 }
 }
 </style>
</head>
<body>
 <header class="header">
 <h1 class="logo">My Site</h1>
 <div class="hamburger" onclick="toggleMenu()">☰</div>
 <nav class="nav-menu" id="navMenu">
 <a href="#">Home</a>
 <a href="#">About</a>
 <a href="#">Services</a>
 <a href="#">Contact</a>
 </nav>
 </header>
 <script>
 function toggleMenu() {
 const navMenu = document.getElementById('navMenu');
 navMenu.style.display = navMenu.style.display === 'flex' ? 'none' : 'flex';
 }
 </script>
</body>
