 position: relative;
 display: inline-block;
 cursor: pointer;
 }
 .tooltip .tooltiptext {
 visibility: hidden;
 width: 120px;
 background-color: #333;
 color: #fff;
 text-align: center;
 border-radius: 5px;
 padding: 8px 0;
 position: absolute;
 z-index: 1;
 bottom: 125%;
 left: 50%;
 margin-left: -60px;
 opacity: 0;
 transition: opacity 0.3s;
 }
 .tooltip:hover .tooltiptext {
 visibility: visible;
 opacity: 1;
 }
 </style>
</head>
<body>

