```html
<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <style>
 .drag-container {
 width: 300px;
 height: 200px;
 border: 2px dashed #ccc;
 border-radius: 5px;
 display: flex;
 flex-wrap: wrap;
 justify-content: center;
 align-items: center;
 padding: 10px;
 margin: 20px auto;
 }
 .draggable-item {
 width: 50px;
 height: 50px;
 background-color: #f0f0f0;
 border: 1px solid #999;
 border-radius: 3px;
 margin: 5px;
 cursor: grab;
 }
 </style>
 <title>Drag and Drop Example</title>
</head>
<body>

<div class="drag-container" id="dragContainer">
 <div class="draggable-item" draggable="true">Item 1</div>
 <div class="draggable-item" draggable="true">Item 2</div>
 <div class="draggable-item" draggable="true">Item 3</div>
</div>

<script>
 const dragContainer = document.getElementById('dragContainer');
 dragContainer.addEventListener('dragover', (e) => {
 e.preventDefault();
 });
 dragContainer.addEventListener('drop', (e) => {
 e.preventDefault();
 const id = e.dataTransfer.getData('text');
 const draggableElement = document.getElementById(id);
 dragContainer.appendChild(draggableElement);
 });

 const draggableItems = document.querySelectorAll('.draggable-item');
 draggableItems.forEach(item => {
 item.addEventListener('dragstart', (e) => {
 e.dataTransfer.setData('text', e.target.id);
 });
 });
</script>

</body>
</html>
```
