 }
 .menu-toggle {
 display: block;
 cursor: pointer;
 font-size: 1.5em;
 color: white;
 }
 /* Responsive Styles */
 @media (min-width: 600px) {
 .nav-links {
 display: flex;
 }
 .menu-toggle {
 display: none;
 }
 }
 </style>
</head>
