 <i class="fa fa-bars">&#9776;</i>
 </a>
</div>

<script>
 function myFunction() {
 var x = document.getElementById("myTopnav");
 if (x.className === "nav-bar") {
 x.className += " responsive";
 } else {
 x.className = "nav-bar";
 }
 }
</script>

