 .tooltip {
 position: relative;
 display: inline-block;
 cursor: pointer;
 }
 .tooltip .tooltip-text {
 visibility: hidden;
 width: 200px;
 background-color: #555;
 color: #fff;
 text-align: center;
 border-radius: 6px;
 padding: 8px 0;
 position: absolute;
 z-index: 1;
 bottom: 125%;
 left: 50%;
 margin-left: -100px;
 opacity: 0;
 transition: opacity 0.3s;
 }
 .tooltip:focus .tooltip-text,
 .tooltip:hover .tooltip-text {
 visibility: visible;
 opacity: 1;
 }
 </style>
</head>
