Here's a complete HTML snippet using semantic HTML5 tags and some CSS for styling:

```html
<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>React Tooltip Example</title>
 <style>
 .tooltip {
 position: relative;
 display: inline-block;
 cursor: pointer;
 }
 .tooltip-text {
 visibility: hidden;
 width: 120px;
 background-color: #555;
 color: #fff;
 text-align: center;
 border-radius: 5px;
 padding: 5px;
 position: absolute;
 z-index: 1;
 bottom: 125%;
 left: 50%;
 margin-left: -60px;
 opacity: 0;
 transition: opacity 0.3s;
 }
 .tooltip:hover .tooltip-text {
 visibility: visible;
 opacity: 1;
 }
 </style>
</head>
<body>
 <div id="app"></div>
 <script type="text/javascript">
 // React component
 function Tooltip({ text, children }) {
 const [showTooltip, setShowTooltip] = React.useState(false);

 return (
 <div className="tooltip"
 onMouseEnter={() => setShowTooltip(true)}
 onMouseLeave={() => setShowTooltip(false)}>
 {children}
 {showTooltip && (
 <span className="tooltip-text">{text}</span>
 )}
 </div>
 );
 }

 function App() {
 return (
 <div>
 <h1>React Tooltip Example</h1>
 <Tooltip text="This is a tooltip">Hover over me</Tooltip>
 </div>
 );
 }

 ReactDOM.render(<App />, document.getElementById('app'));
 </script>
 <!-- Include React and ReactDOM via CDN for simplicity -->
 <script src="https://unpkg.com/react/umd/react.development.js"></script>
 <script src="https://unpkg.com/react-dom/umd/react-dom.development.js"></script>
</body>
</html>
```

**Explanation:**
- We define a `Tooltip` component that manages its own state using `useState` to determine when to show the tooltip text.
- The tooltip text is shown when the mouse hovers over the `Tooltip` div, thanks to the `onMouseEnter` and `onMouseLeave` events.

