 <div></div>
 <div></div>
 <div></div>
 </div>
 </div>
 </header>
 <script>
 function toggleMenu() {
 const menu = document.querySelector('.menu');
 if (menu.style.display === 'flex') {
 menu.style.display = 'none';
 } else {
 menu.style.display = 'flex';
 }
 }
 </script>
</body>
</html>
