 <title>Responsive Modal Window</title>
 <style>
 body {
 font-family: Arial, sans-serif;
 margin: 0;
 padding: 0;
 box-sizing: border-box;
 }
 .modal {
 display: none;
 position: fixed;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 background-color: rgba(0, 0, 0, 0.7);
 justify-content: center;
 align-items: center;
 }
 .modal-content {
 background-color: #fff;
 padding: 20px;
 border-radius: 5px;
 width: 90%;
 max-width: 500px;
 box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
 }
 .modal-header {
 font-size: 1.5em;
 margin-bottom: 15px;
 }
 .modal-body {
 margin-bottom: 15px;
 }
 .modal-footer {
 text-align: right;
 }
 .close-btn {
 background-color: #007BFF;
 color: #fff;
 border: none;
 padding: 10px 20px;
 border-radius: 5px;
 cursor: pointer;
 font-size: 1em;
 }
 </style>
</head>
<body>
